steps.analogousExample:
/* Example: styling a container and items */
.container {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
    padding: 20px;
}

.item {
    width: 100px;
    height: 100px;
    background-color: lightblue;
    border-radius: 8px;
}

/* Example of clipping an element to a circle */
.box1 {
  clip-path: circle(50%);
}

/* Example of a polygon with percentage coordinates */
.box2 {
  clip-path: polygon(0% 0%, 100% 0%, 50% 100%);
}

